def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    marker = min(counts, key=counts.get)
    coords = [(i,j) for i,row in enumerate(grid) for j,x in enumerate(row) if x == marker]
    r0=min(i for i,j in coords); r1=max(i for i,j in coords)
    c0=min(j for i,j in coords); c1=max(j for i,j in coords)
    mask={(i-r0,j-c0) for i,j in coords}
    out=[row[:] for row in grid]
    for i in range(h-(r1-r0)):
        for j in range(w-(c1-c0)):
            if all(grid[i+di][j+dj] == 0 for di,dj in mask):
                for di,dj in mask:
                    out[i+di][j+dj] = marker
    return out
